  SWIG_Python_SetConstant(d, "DType_Int64",SWIG_From_int(static_cast< int >(datamunge::nn::DType::Int64)));
  SWIG_Python_SetConstant(d, "DType_Float32",SWIG_From_int(static_cast< int >(datamunge::nn::DType::Float32)));
  SWIG_Python_SetConstant(d, "DType_Float64",SWIG_From_int(static_cast< int >(datamunge::nn::DType::Float64)));
  SWIG_Python_SetConstant(d, "PadMode_Constant",SWIG_From_int(static_cast< int >(datamunge::nn::PadMode::Constant)));
  SWIG_Python_SetConstant(d, "PadMode_Reflect",SWIG_From_int(static_cast< int >(datamunge::nn::PadMode::Reflect)));
  SWIG_Python_SetConstant(d, "PadMode_Symmetric",SWIG_From_int(static_cast< int >(datamunge::nn::PadMode::Symmetric)));
  SWIG_Python_SetConstant(d, "Padding_Same",SWIG_From_int(static_cast< int >(datamunge::nn::Padding::Same)));
  SWIG_Python_SetConstant(d, "Padding_Valid",SWIG_From_int(static_cast< int >(datamunge::nn::Padding::Valid)));
